<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('customers.view');$q=trim((string)($_GET['q']??''));$debt=(string)($_GET['debt']??'');$status=(string)($_GET['status']??'active');$page=max(1,(int)($_GET['page']??1));$per=25;$where=['1=1'];$params=[];if($q!==''){$where[]='(c.name LIKE :q OR c.phone LIKE :q OR c.email LIKE :q)';$params[':q']='%'.$q.'%';}if($status!=='all'){$where[]='c.status=:status';$params[':status']=in_array($status,['active','inactive'],true)?$status:'active';}if($debt==='yes')$where[]='c.account_balance>0';$ws=implode(' AND ',$where);$cnt=db()->prepare("SELECT COUNT(*) FROM customers c WHERE $ws");$cnt->execute($params);$total=(int)$cnt->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$off=($page-1)*$per;$st=db()->prepare("SELECT c.*,(SELECT COUNT(*) FROM sales s WHERE s.customer_id=c.id AND s.status='completed') sales_count FROM customers c WHERE $ws ORDER BY c.name LIMIT $per OFFSET $off");$st->execute($params);$rows=$st->fetchAll();$summary=db()->query('SELECT COUNT(*) total,SUM(status="active") active_count,COALESCE(SUM(CASE WHEN account_balance>0 THEN account_balance ELSE 0 END),0) debt_total,SUM(account_balance>0) debtors FROM customers')->fetch()?:[];
$pageTitle='Customers';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><?php require BASE_PATH.'/includes/alerts.php';?><div class="page-toolbar"><div><span class="eyebrow">Customer accounts</span><h2>Customers</h2><p>Sales history, contact details and customer credit balances.</p></div><?php if(user_can('customers.create')):?><a class="button button--primary" href="<?=e(app_url('customers/add.php'))?>">+ Add customer</a><?php endif;?></div><section class="mini-metric-grid"><article class="mini-metric"><span>Total customers</span><strong><?=e((string)($summary['total']??0))?></strong></article><article class="mini-metric"><span>Active</span><strong><?=e((string)($summary['active_count']??0))?></strong></article><article class="mini-metric"><span>Debtors</span><strong><?=e((string)($summary['debtors']??0))?></strong></article><article class="mini-metric"><span>Outstanding debt</span><strong><?=e(money($summary['debt_total']??0))?></strong></article></section>
<section class="panel-card table-panel"><form class="filter-bar" method="get"><div class="filter-search"><input name="q" value="<?=e($q)?>" placeholder="Search name, phone or email"></div><select name="debt"><option value="">All balances</option><option value="yes" <?=$debt==='yes'?'selected':''?>>With debt</option></select><select name="status"><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>Inactive</option><option value="all" <?=$status==='all'?'selected':''?>>All</option></select><button class="button button--secondary">Filter</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Phone</th><th>Sales</th><th>Credit limit</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7"><div class="empty-state"><strong>No customers found</strong></div></td></tr><?php else:foreach($rows as$c):?><tr><td><div class="table-user"><div class="avatar avatar--small"><?=e(initials($c['name']))?></div><div><strong><?=e($c['name'])?></strong><span><?=e($c['email']?:'No email')?></span></div></div></td><td><?=e($c['phone']?:'—')?></td><td><?=e((string)$c['sales_count'])?></td><td><?=e(money($c['credit_limit']))?></td><td><strong class="<?=((float)$c['account_balance']>0?'text-warning':'')?>"><?=e(money($c['account_balance']))?></strong></td><td><span class="status-badge status-badge--<?=e($c['status'])?>"><?=e(ucfirst($c['status']))?></span></td><td class="table-action-cell"><a class="table-action" href="<?=e(app_url('customers/view.php?id='.(int)$c['id']))?>">View</a></td></tr><?php endforeach;endif;?></tbody></table></div><div class="table-footer"><span>Showing <?=$total===0?0:$off+1?>–<?=min($off+$per,$total)?> of <?=$total?></span></div></section></main></div><?php require BASE_PATH.'/includes/footer.php';?>
